// Define tables

export const agentTable = table('agents')
  .columns({
    id: string(),
    userDefinedId: string(),
    modelId: string(),
    workspaceId: string(),
    systemPrompt: string(),
    description: string().optional(),
    name: string(),
    version: number(),
    updatedAt: number(),
    createdAt: number(),
    temp: number().optional(),
    scope: string(),
    scopeURI: string().optional(),
  })
  .primaryKey('id');

export const modelTable = table('models')
  .columns({
    id: string(),
    userDefinedId: string(),
    workspaceId: string(),
    name: string(),
    provider: string(),
    credentials: string(),
    createdAt: number(),
    updatedAt: number(),
  })
  .primaryKey('id');

