export const userTable = table('users')
  .columns({
    id: string(),
    name: string(),
    email: string(),
    picture: string().optional(),
    authProvider: enumeration<AuthProvider>(),
    providerUserId: string(),
    status: enumeration<UserStatus>(),
    userType: enumeration<UserType>(),
    metadata: json().optional(),
    displayName: string().optional(),
    workspaceId: string(),
    role: enumeration<WorkspaceRole>(),
    orgMemberId: string(),
    leftAt: number().optional(),
    createdAt: number(),
    updatedAt: number(),
    // Presence display fields promoted from user_presence for query performance (dual-written)
    statusEmoji: string().optional(),
    statusContent: string().optional(),
    statusExpiryAt: number().optional(),
    lastActiveAt: number().optional(),
    /** Global notification pause promoted from user_presence for query performance (dual-written) */
    notificationsPausedUntil: number().optional(),
    /** Assignment availability promoted from user_presence for query performance (dual-written) */
    assignmentUnavailableUntil: number().optional(),
  })
  .primaryKey('id');

export const userPresenceTable = table('user_presence')
  .columns({
    id: string(),
    userId: string(),
    status: enumeration<UserPresenceStatus>(),
    /** @deprecated use users.lastActiveAt — dual-written for backward compat */
    lastActiveAt: number(),
    lastSeenAt: number(),
    isManual: boolean(),
    deviceInfo: string().optional(),
    /** @deprecated use users.statusEmoji — dual-written for backward compat */
    statusEmoji: string().optional(),
    /** @deprecated use users.statusContent — dual-written for backward compat */
    statusContent: string().optional(),
    /** @deprecated use users.statusExpiryAt — dual-written for backward compat */
    statusExpiryAt: number().optional(),
    assignmentUnavailableUntil: number().optional(), // When user will be available for ticket assignment again
    /** @deprecated use users.notificationsPausedUntil — dual-written for backward compat */
    notificationsPausedUntil: number().optional(), // Global notification pause (Slack-style "Pause notifications") - applies to all channels
    createdAt: number(),
    updatedAt: number(),
  })
  .primaryKey('id');

export const userProfileTable = table('user_profiles')
  .columns({
    id: string(),
    userId: string(),
    dob: number().optional(), // Date of birth (optional) - stored as timestamp
    phoneNumber: string().optional(), // Phone number (optional)
    displayName: string().optional(), // Display name (optional)
    team: string().optional(), // Team name/identifier (optional)
    pronunciation: string().optional(), // Name pronunciation guide (optional)
    manager: string().optional(), // Manager userId (optional)
    role: string().optional(), // User role (optional)
    joinedOn: number().optional(), // Date when user joined (optional for backfill) - stored as timestamp
    hasVoiceSignature: boolean().optional(), // Zero-syncable flag derived from voiceSignature presence
    createdAt: number(),
    updatedAt: number(),
  })
  .primaryKey('id');

export const userPreferenceTable = table('user_preferences')
